llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Oral LSD in 20 healthy participants had an absolute bioavailability of 80% (72–90%) versus IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tolfenamic acid after 100 mg oral versus IV in healthy female volunteers had an absolute bioavailability of 63.2%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Magnesium L-lactate ER caplets in fed healthy adults had a serum-based absolute bioavailability of 12.49%, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple direct human absolute oral bioavailability measurements transferred with high assay-transfer scores are above 20% (80%, 74–75%, 63.2%, 49%, 24%), supporting high bioavailability; one mixed matrix-dependent value and qualitative reports lower confidence but do not overturn the positive direction.",
  "evidence_gaps": [
    "Molecule 7 absolute bioavailability is matrix-dependent (serum 12.49–20.26%, urine 38.11–40.99%), making its direction mixed.",
    "Molecules 9 and 10 report only qualitative 'good bioavailability' without numeric F values.",
    "Molecule 8 average F is 49% but individual values range from 5% to 74%, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

